  it("advances to a new shelter frontier when every nearby shaft is rejected", async () => {
    const driver = new FakeBeatGameDriver();
    driver.currentEnvironment = { gameTime: 14_000n };
    driver.currentObservation = observation({
      counts: {
        "minecraft:dirt": 1,
        "minecraft:wooden_sword": 1,
      },
      position: { x: 0.5, y: 64, z: 0.5 },
    });
    driver.surfaceQueryResolver = (center) => {
      if (center.x < 8) {
        return [
          {
            x: 0,
            z: 0,
            loaded: true,
            surfaceY: 63,
            blockId: "minecraft:water",
            biomeId: "minecraft:river",
            skyLight: 15,
            blockLight: 0,
          },
        ];
      }
      return [-1, 0, 1].flatMap((deltaX) =>
        [-1, 0, 1].map((deltaZ) => ({
          x: 16 + deltaX,
          z: deltaZ,
          loaded: true,
          surfaceY: 63,
          blockId: "minecraft:grass_block",
          biomeId: "minecraft:plains",
          skyLight: 15,
          blockLight: 0,
        })),
      );
    };
    const removedBlocks = new Set<string>();
    const key = (x: number, y: number, z: number) => `${x}:${y}:${z}`;
    let sealPlaced = false;
    driver.blockQueryResolver = ({ center, selector }) => {
      if (selector.blockIds?.includes("minecraft:water") === true) {
        return [];
      }
      const position = {
        x: Math.floor(center.x),
        y: Math.floor(center.y),
        z: Math.floor(center.z),
        dimension: center.dimension,
      };
      const blockKey = key(position.x, position.y, position.z);
      const stableShaft = position.x === 16 && position.z === 0;
      const stableSeal = stableShaft && position.y === 63;
      const stableSupport = position.x === 17 && position.y === 63 && position.z === 0;
      const stableFloor =
        stableShaft && position.y >= 61 && position.y <= 63 && !removedBlocks.has(blockKey);
      if ((stableSeal && sealPlaced) || stableSupport || stableFloor) {
        return [
          blockObservation(position, {
            blockId: stableSeal && sealPlaced ? "minecraft:dirt" : "minecraft:stone",
          }),
        ];
      }
      return [
        blockObservation(position, {
          blockId: "minecraft:air",
          diggable: false,
          replaceable: true,
          solid: false,
        }),
      ];
    };
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
        driver.currentObservation = observation({
          counts: driver.currentObservation.inventory.counts,
          position,
        });
      });
    driver.actionObserver = (action) => {
      if (action.type === "dig-block") {
        removedBlocks.add(key(action.position.x, action.position.y, action.position.z));
        driver.currentObservation = observation({
          counts: driver.currentObservation.inventory.counts,
          position: {
            ...driver.currentObservation.player.position,
            y: driver.currentObservation.player.position.y - 1,
          },
        });
      }
      if (action.type === "place-block") {
        sealPlaced = true;
        removedBlocks.delete(key(16, 63, 0));
        driver.currentEnvironment = { gameTime: 1_000n };
      }
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (
            !driver.actions.some(
              (action) => action.type === "dig-block" && action.position.x === 16,
            )
          ) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
          yield* run.awaitCompletion.pipe(Effect.result);
        }).pipe(
          Effect.timeoutOrElse({
            duration: "5 seconds",
            orElse: () => Effect.fail(new Error("Timed out waiting for shelter relocation")),
          }),
        ),
      ),
    );

    expect(driver.paths[0]).toMatchObject({
      position: {
        x: 16.5,
        y: 64,
        z: 0.5,
        dimension: "minecraft:overworld",
      },
      policy: {
        allowMining: false,
        allowPlacing: false,
        avoidFluids: true,
      },
    });
    expect(driver.actions).not.toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          type: "dig-block",
          position: expect.objectContaining({ x: 0, z: 0 }),
        }),
      ]),
    );
  }, 10_000);

