  it("increases the respawn delay after repeated corpse-recovery deaths", async () => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const firstObservedAt = new Date(Date.now() - 120_000).toISOString();
    const secondObservedAt = new Date(Date.now() - 60_000).toISOString();
    const thirdObservedAt = new Date().toISOString();
    const initial = checkpoint(BeatGamePhase.PREPARE_OVERWORLD, {
      runId: "chained-death-cooldown-run",
      teamId: "chained-death-cooldown-team",
    });
    await Effect.runPromise(
      store.save(
        {
          ...initial,
          memory: {
            ...initial.memory,
            deathPositions: [
              {
                key: `death:${firstObservedAt}`,
                value: {
                  x: 80,
                  y: 64,
                  z: 0,
                  dimension: "minecraft:overworld",
                  inventoryCounts: { "minecraft:iron_ingot": 7 },
                },
                observedAt: firstObservedAt,
                confidence: 1,
              },
              {
                key: `death:${secondObservedAt}`,
                value: {
                  x: 4,
                  y: 64,
                  z: 0,
                  dimension: "minecraft:overworld",
                  inventoryCounts: { "minecraft:oak_log": 4 },
                },
                observedAt: secondObservedAt,
                confidence: 1,
              },
              {
                key: `death:${thirdObservedAt}`,
                value: {
                  x: 8,
                  y: 64,
                  z: 0,
                  dimension: "minecraft:overworld",
                  inventoryCounts: { "minecraft:rotten_flesh": 1 },
                },
                observedAt: thirdObservedAt,
                confidence: 1,
              },
            ],
          },
        },
        undefined,
      ),
    );
    driver.currentObservation = observation({
      dead: true,
      health: 0,
      food: 5,
    });

    const [diagnostic, interruptedDuringCooldown] = await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            runId: "chained-death-cooldown-run",
            team: { teamId: "chained-death-cooldown-team" },
            checkpointStore: store,
            strategy: { observationPollMs: 1 },
          });
          const event = yield* run.events.pipe(
            Stream.filter(
              (candidate) =>
                candidate.type === "diagnostic" &&
                candidate.message === "Delaying respawn after a chained corpse-recovery death",
            ),
            Stream.runHead,
            Effect.timeout("5 seconds"),
          );
          const interrupted = yield* Effect.race(
            run.events.pipe(
              Stream.filter(
                (candidate) =>
                  candidate.type === "action-failed" &&
                  candidate.detail?.includes("hunger became urgent without available food") ===
                    true,
              ),
              Stream.runHead,
              Effect.as(true),
            ),
            Effect.sleep(25).pipe(Effect.as(false)),
          );
          yield* run.stop;
          yield* run.awaitCompletion.pipe(Effect.result);
          return [event, interrupted] as const;
        }),
      ),
    );

    expect(Option.getOrUndefined(diagnostic)).toMatchObject({
      type: "diagnostic",
      data: {
        cooldownMs: 120_000,
        pendingDeaths: 3,
      },
    });
    expect(driver.tasks).not.toContainEqual(
      expect.objectContaining({
        type: "auto-respawn",
      }),
    );
    expect(interruptedDuringCooldown).toBe(false);
  });

