  it("knocks back a zombie that catches a corpse recovery flee route", async () => {
    const driver = new FakeBeatGameDriver();
    const deathPosition = {
      x: 24,
      y: 64,
      z: -12,
      dimension: "minecraft:overworld",
    };
    const zombie = {
      connectionEpoch: "epoch-1",
      networkId: 34,
      entityType: "minecraft:zombie",
      position: {
        x: 2,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:01.000Z",
    } as const;
    driver.currentObservation = observation({
      dead: true,
      health: 0,
      position: deathPosition,
      counts: { "minecraft:iron_ingot": 7 },
    });
    driver.entityQueryResolver = (query) =>
      query.selector.categories?.includes(2) || query.selector.networkId === zombie.networkId
        ? [zombie]
        : [];
    let interruptedEscapes = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "flee") {
          driver.currentObservation = observation({ health: 3 });
        }
      }).pipe(
        Effect.andThen(task.type === "flee" ? Effect.never : Effect.void),
        Effect.onInterrupt(() =>
          Effect.sync(() => {
            if (task.type === "flee") {
              interruptedEscapes += 1;
            }
          }),
        ),
      );

    const stateBeforeStop = await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
          hooks: {
            recoverDeath: () =>
              Effect.sync(() => {
                driver.currentObservation = observation({ health: 6 });
                driver.entityResults = [zombie];
              }).pipe(Effect.andThen(Effect.never)),
          },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (!driver.tasks.some((task) => task.type === "flee")) {
                yield* Effect.sleep(1);
              }
              yield* Effect.sleep(250);
              const result = {
                interruptedEscapes,
                fleeTasks: driver.tasks.filter((task) => task.type === "flee").length,
              };
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
              return result;
            }),
          ),
        ),
      ),
    );

    expect(stateBeforeStop.interruptedEscapes).toBeGreaterThanOrEqual(1);
    expect(stateBeforeStop.fleeTasks).toBeGreaterThanOrEqual(1);
    const fleeIndex = driver.tasks.findIndex((task) => task.type === "flee");
    expect(driver.taskPolicies[fleeIndex]?.allowMining).toBe(false);
    expect(driver.actions).toContainEqual({
      type: "attack-entity",
      connectionEpoch: zombie.connectionEpoch,
      networkId: zombie.networkId,
      sprinting: true,
    });
    expect(
      driver.actions.some((action) => action.type === "set-movement" && action.forward === true),
    ).toBe(false);
  }, 10_000);

