  it("keeps monitoring for new attackers after resuming item recovery", async () => {
    const driver = new FakeBeatGameDriver();
    const deathObservedAt = new Date().toISOString();
    const deathPosition = {
      x: 20,
      y: 64,
      z: 20,
      dimension: "minecraft:overworld",
    };
    const attackers = [31, 32].map(
      (networkId) =>
        ({
          connectionEpoch: "epoch-1",
          networkId,
          entityType: "minecraft:zombie",
          position: {
            x: 2,
            y: 64,
            z: 0,
            dimension: "minecraft:overworld",
          },
          velocity: { x: 0, y: 0, z: 0 },
          alive: true,
          health: 20,
          observedAt: "2026-01-01T00:00:01.000Z",
        }) as const,
    );
    driver.currentObservation = observation({
      dead: true,
      health: 0,
      observedAt: deathObservedAt,
      position: deathPosition,
    });
    driver.entityQueryResolver = (query) =>
      query.selector.categories?.includes(2) ? driver.entityResults : [];
    driver.taskObserver = (task) => {
      if (task.type === "attack-entity") {
        driver.entityResults = [];
      }
    };
    let recoveries = 0;

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
          hooks: {
            recoverDeath: () => {
              const waitForInterruption = recoveries < attackers.length;
              return Effect.sync(() => {
                driver.currentObservation = observation();
                const attacker = attackers[recoveries];
                driver.entityResults = attacker === undefined ? [] : [attacker];
                recoveries += 1;
              }).pipe(Effect.andThen(waitForInterruption ? Effect.never : Effect.void));
            },
          },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (recoveries < 3) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(recoveries).toBe(3);
    expect(driver.tasks.filter((task) => task.type === "attack-entity")).toHaveLength(2);
  });

