  it("keeps escaping a nearby creeper when a ranged attacker deals damage", async () => {
    const driver = new FakeBeatGameDriver();
    const creeper = {
      connectionEpoch: "epoch-1",
      networkId: 41,
      entityType: "minecraft:creeper",
      position: {
        x: 6,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:01.000Z",
    } as const;
    const skeleton = {
      ...creeper,
      networkId: 42,
      entityType: "minecraft:skeleton",
      position: { ...creeper.position, x: 8 },
    } as const;
    driver.entityResults = [creeper];
    let interruptedEscapes = 0;
    let escapes = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type !== "flee") {
          return;
        }
        escapes += 1;
        driver.entityResults = [creeper, skeleton];
        driver.currentObservation = observation({ health: 17 });
      }).pipe(
        Effect.andThen(task.type === "flee" ? Effect.never : Effect.void),
        Effect.onInterrupt(() =>
          Effect.sync(() => {
            if (task.type === "flee") {
              interruptedEscapes += 1;
            }
          }),
        ),
      );

    const interruptedBeforeStop = await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (escapes === 0) {
                yield* Effect.sleep(1);
              }
              yield* Effect.sleep(250);
              const result = interruptedEscapes;
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
              return result;
            }),
          ),
        ),
      ),
    );

    expect(interruptedBeforeStop).toBe(0);
    expect(escapes).toBe(1);
    expect(driver.tasks).not.toContainEqual(
      expect.objectContaining({
        type: "attack-entity",
      }),
    );
    expect(driver.tasks.filter((task) => task.type === "flee")).toHaveLength(1);
  }, 10_000);

