              const event = yield* run.events.pipe(
                Stream.filter(
                  (candidate) =>
                    candidate.type === "action-succeeded" && candidate.action === "retreat",
                ),
                Stream.runHead,
              );
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
              return event;
