  it("defends against a hostile that approaches during recovery", async () => {
    const driver = new FakeBeatGameDriver();
    const zombie = {
      connectionEpoch: "epoch-1",
      networkId: 18,
      entityType: "minecraft:zombie",
      position: {
        x: 2,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    const rottenFlesh = {
      connectionEpoch: "epoch-1",
      networkId: 19,
      entityType: "minecraft:item",
      itemId: "minecraft:rotten_flesh",
      itemCount: 1,
      position: {
        x: 2,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 5,
      observedAt: "2026-01-01T00:00:01.000Z",
    } as const;
    driver.currentObservation = observation({
      health: 20,
      counts: { "minecraft:cooked_beef": 1 },
    });
    let hostileQueries = 0;
    let zombieNearby = false;
    let zombieDefeated = false;
    driver.entityQueryResolver = (query) => {
      if (query.selector.entityTypes?.includes("minecraft:item")) {
        return zombieDefeated ? [rottenFlesh] : [];
      }
      if (!query.selector.categories?.includes(2)) {
        return [];
      }
      hostileQueries += 1;
      if (hostileQueries >= 2 && !zombieDefeated) {
        zombieNearby = true;
      }
      return zombieNearby ? [zombie] : [];
    };
    driver.taskObserver = (task) => {
      if (task.type === "attack-entity") {
        zombieDefeated = true;
        zombieNearby = false;
      }
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (!driver.tasks.some((task) => task.type === "attack-entity")) {
                yield* Effect.sleep(1);
              }
              while (
                !driver.paths.some(
                  ({ position }) =>
                    position.x === rottenFlesh.position.x &&
                    position.y === rottenFlesh.position.y &&
                    position.z === rottenFlesh.position.z,
                )
              ) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(hostileQueries).toBeGreaterThanOrEqual(2);
    expect(driver.tasks).toContainEqual(
      expect.objectContaining({
        type: "attack-entity",
        target: expect.objectContaining({ networkId: zombie.networkId }),
        selectBestWeapon: true,
      }),
    );
    expect(driver.paths).toContainEqual(
      expect.objectContaining({
        position: rottenFlesh.position,
        radius: 1.25,
        policy: expect.objectContaining({
          allowPlacing: false,
          avoidFluids: true,
        }),
      }),
    );
  });

  it("preempts a recovery fight when a closer melee hostile arrives", async () => {
    const driver = new FakeBeatGameDriver();
    const firstZombie = {
      connectionEpoch: "epoch-1",
      networkId: 201,
      entityType: "minecraft:zombie",
      position: {
        x: 2,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    const skeleton = {
      connectionEpoch: "epoch-1",
      networkId: 202,
      entityType: "minecraft:skeleton",
      position: {
        x: 8,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:01.000Z",
    } as const;
    const closingZombie = {
      connectionEpoch: "epoch-1",
      networkId: 203,
      entityType: "minecraft:zombie",
      position: {
        x: 1.5,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:02.000Z",
    } as const;
    driver.currentObservation = observation({
      health: 20,
      counts: {
        "minecraft:cooked_beef": 1,
        "minecraft:shield": 1,
        "minecraft:stone_sword": 1,
      },
    });
    driver.entityQueryResolver = (query) => {
      if (query.selector.networkId !== undefined) {
        return driver.entityResults.filter(
          (entity) => entity.networkId === query.selector.networkId,
        );
      }
      return query.selector.categories?.includes(2) ? driver.entityResults : [];
    };
    let skeletonInterrupted = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "attack-entity" && task.target.networkId === firstZombie.networkId) {
          driver.entityResults = [skeleton];
        }
        if (task.type === "attack-entity" && task.target.networkId === closingZombie.networkId) {
          driver.entityResults = [];
        }
      }).pipe(
        Effect.andThen(
          task.type === "collect-blocks"
            ? Effect.never
            : task.type === "attack-entity" && task.target.networkId === skeleton.networkId
              ? Effect.never
              : Effect.void,
        ),
        Effect.onInterrupt(() =>
          Effect.sync(() => {
            if (task.type === "attack-entity" && task.target.networkId === skeleton.networkId) {
              skeletonInterrupted += 1;
            }
          }),
        ),
      );

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (!driver.tasks.some((task) => task.type === "collect-blocks")) {
                yield* Effect.sleep(1);
              }
              driver.entityResults = [firstZombie];
              while (
                !driver.tasks.some(
                  (task) =>
                    task.type === "attack-entity" && task.target.networkId === skeleton.networkId,
                )
              ) {
                yield* Effect.sleep(1);
              }
              driver.entityResults = [skeleton, closingZombie];
              while (
                !driver.tasks.some(
                  (task) =>
                    task.type === "attack-entity" &&
                    task.target.networkId === closingZombie.networkId,
                )
              ) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(skeletonInterrupted).toBeGreaterThanOrEqual(1);
    expect(driver.tasks).toContainEqual(
      expect.objectContaining({
        type: "attack-entity",
        target: expect.objectContaining({
          networkId: closingZombie.networkId,
        }),
        selectBestWeapon: true,
      }),
    );
  }, 10_000);

