  it("stops an escape route once its threat is no longer nearby", async () => {
    const driver = new FakeBeatGameDriver();
    const skeleton = {
      connectionEpoch: "epoch-1",
      networkId: 17,
      entityType: "minecraft:skeleton",
      position: {
        x: 6,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    driver.currentObservation = observation({ health: 8 });
    driver.entityResults = [skeleton];
    let targetNearby = true;
    driver.entityQueryResolver = (query) =>
      query.selector.networkId === skeleton.networkId
        ? targetNearby
          ? [skeleton]
          : []
        : query.selector.categories?.includes(2)
          ? driver.entityResults
          : [];
    let interruptedEscapes = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        driver.taskObserver(task);
        if (task.type === "flee") {
          targetNearby = false;
          driver.entityResults = [];
        }
      }).pipe(
        Effect.andThen(task.type === "flee" ? Effect.never : Effect.void),
        Effect.onInterrupt(() =>
          Effect.sync(() => {
            if (task.type === "flee") {
              interruptedEscapes += 1;
            }
          }),
        ),
      );

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (interruptedEscapes === 0) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.tasks).toContainEqual(
      expect.objectContaining({
        type: "flee",
        selector: { categories: [2], alive: true },
        triggerRadius: 24,
        safeDistance: 32,
      }),
    );
    expect(interruptedEscapes).toBe(1);
    expect(driver.entityQueries).toContainEqual(
      expect.objectContaining({
        radius: 32,
        selector: {
          networkId: skeleton.networkId,
          alive: true,
        },
        maximumResults: 1,
      }),
    );
  });

