  it("abandons a blocked shore and clears the immediate swimming ceiling", async () => {
    const driver = new FakeBeatGameDriver();
    const preparedItems = {
      "minecraft:oak_log": 8,
      "minecraft:cobblestone": 20,
      "minecraft:stone_sword": 1,
      "minecraft:stone_pickaxe": 1,
      "minecraft:beef": 8,
    };
    driver.surfaceQueryResolver = () =>
      [-1, 0, 1].map((z) => ({
        x: 1,
        z,
        loaded: true,
        surfaceY: 63,
        blockId: "minecraft:grass_block",
        biomeId: "minecraft:plains",
        skyLight: 15,
        blockLight: 0,
      }));
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
      }).pipe(Effect.andThen(Effect.never));
    let overheadCleared = false;
    let swimmingTowardShore = false;
    let escapedFromFluid = false;
    let resolveEscaped!: () => void;
    const escaped = new Promise<void>((resolve) => {
      resolveEscaped = resolve;
    });
    driver.blockQueryResolver = (query) => {
      const blockX = Math.floor(query.center.x);
      const blockY = Math.floor(query.center.y);
      const blockZ = Math.floor(query.center.z);
      const blockIds = query.selector.blockIds;
      if (blockIds?.includes("minecraft:water") === true && !escapedFromFluid) {
        return [
          blockObservation(
            {
              x: blockX,
              y: blockY,
              z: blockZ,
              dimension: query.center.dimension,
            },
            {
              blockId: "minecraft:water",
              diggable: false,
              replaceable: true,
            },
          ),
        ];
      }
      if (blockIds === undefined) {
        const immediateCeiling = blockX === 0 && blockY === 63 && blockZ === 0;
        return immediateCeiling && overheadCleared
          ? [
              blockObservation(
                {
                  x: 0,
                  y: 63,
                  z: 0,
                  dimension: "minecraft:overworld",
                },
                {
                  blockId: "minecraft:air",
                  diggable: false,
                  replaceable: true,
                },
              ),
            ]
          : [
              blockObservation(
                {
                  x: blockX,
                  y: blockY,
                  z: blockZ,
                  dimension: query.center.dimension,
                },
                { hardness: 0.1 },
              ),
            ];
      }
      return [];
    };
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
      }).pipe(
        Effect.flatMap(() =>
          overheadCleared
            ? Effect.void
            : Effect.fail(
                new BeatGameDriverError({
                  operation: "pathfind",
                  code: "unreachable",
                  retryable: true,
                  message: "The submerged cavity has no navigable exit",
                }),
              ),
        ),
      );
    driver.actionObserver = (action) => {
      const current = driver.currentObservation;
      if (action.type === "look") {
        driver.currentObservation = {
          ...current,
          player: {
            ...current.player,
            rotation: {
              yaw: action.yaw,
              pitch: action.pitch,
            },
          },
        };
        return;
      }
      if (action.type === "dig-block") {
        overheadCleared = true;
        return;
      }
      if (action.type === "reset-movement") {
        swimmingTowardShore = false;
        return;
      }
      if (action.type !== "set-movement" || action.jump !== true) {
        return;
      }
      if (action.forward === true && current.player.rotation.pitch !== -90) {
        swimmingTowardShore = true;
        return;
      }
      const verticalEscape = action.forward === undefined && overheadCleared;
      if (!verticalEscape) {
        return;
      }
      driver.currentObservation = {
        ...current,
        player: {
          ...current.player,
          air: 300,
          position: {
            ...current.player.position,
            y: 64,
          },
        },
      };
      escapedFromFluid = true;
      resolveEscaped();
    };
    driver.observationResolver = () =>
      Effect.sync(() => {
        if (!swimmingTowardShore) {
          return driver.currentObservation;
        }
        const current = driver.currentObservation;
        driver.currentObservation = {
          ...current,
          player: {
            ...current.player,
            air: current.player.air - 5,
          },
        };
        return driver.currentObservation;
      });

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (!driver.tasks.some((task) => task.type === "collect-blocks")) {
            yield* Effect.sleep(1);
          }
          driver.currentObservation = observation({
            air: 260,
            food: 12,
            counts: preparedItems,
            position: { x: 0.5, y: 62.4, z: 0.5 },
          });
          yield* Effect.promise(() => escaped).pipe(Effect.timeout("10 seconds"));
          yield* run.stop;
        }),
      ),
    );

    expect(driver.actions).toContainEqual({
      type: "select-item",
      selector: {
        itemIds: [
          "minecraft:netherite_pickaxe",
          "minecraft:diamond_pickaxe",
          "minecraft:iron_pickaxe",
          "minecraft:stone_pickaxe",
          "minecraft:wooden_pickaxe",
          "minecraft:golden_pickaxe",
        ],
      },
    });
    expect(driver.actions).toContainEqual({
      type: "dig-block",
      position: {
        x: 0,
        y: 63,
        z: 0,
        dimension: "minecraft:overworld",
      },
    });
    expect(driver.actions).toContainEqual({
      type: "set-movement",
      jump: true,
    });
    const digIndex = driver.actions.findIndex((action) => action.type === "dig-block");
    const heldAscentIndex = driver.actions.findIndex(
      (action, index) =>
        index < digIndex &&
        action.type === "set-movement" &&
        action.forward === undefined &&
        action.jump === true,
    );
    const releaseIndex = driver.actions.findIndex(
      (action, index) => index > digIndex && action.type === "reset-movement",
    );
    expect(heldAscentIndex).toBeGreaterThanOrEqual(0);
    expect(releaseIndex).toBeGreaterThan(digIndex);
    expect(driver.paths).toHaveLength(0);
    expect(driver.currentObservation.player.position.y).toBe(64);
  }, 15_000);

  it("keeps climbing a deep aquifer after surface pathfinding fails", async () => {
    const driver = new FakeBeatGameDriver();
    driver.surfaceColumns = [
      {
        x: 0,
        z: 0,
        loaded: true,
        surfaceY: 63,
        blockId: "minecraft:grass_block",
        biomeId: "minecraft:plains",
        skyLight: 15,
        blockLight: 0,
      },
    ];
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
      }).pipe(Effect.andThen(Effect.never));
    driver.blockQueryResolver = (query) => {
      const position = {
        x: Math.floor(query.center.x),
        y: Math.floor(query.center.y),
        z: Math.floor(query.center.z),
        dimension: query.center.dimension,
      };
      const submerged = driver.currentObservation.player.position.y < 64;
      if (query.selector.blockIds?.includes("minecraft:water") === true) {
        return submerged
          ? [
              blockObservation(position, {
                blockId: "minecraft:water",
                diggable: false,
                replaceable: true,
              }),
            ]
          : [];
      }
      if (query.selector.blockIds === undefined) {
        return [
          blockObservation(position, {
            blockId: submerged ? "minecraft:water" : "minecraft:air",
            diggable: false,
            replaceable: true,
          }),
        ];
      }
      return [];
    };
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
      }).pipe(
        Effect.andThen(
          Effect.fail(
            new BeatGameDriverError({
              operation: "pathfind",
              code: "unreachable",
              retryable: true,
              message: "The deep aquifer has no navigable route to its surface",
            }),
          ),
        ),
      );
    let ascending = false;
    let resolveEscaped!: () => void;
    const escaped = new Promise<void>((resolve) => {
      resolveEscaped = resolve;
    });
    driver.actionObserver = (action) => {
      const current = driver.currentObservation;
      if (action.type === "look") {
        driver.currentObservation = {
          ...current,
          player: {
            ...current.player,
            rotation: { yaw: action.yaw, pitch: action.pitch },
          },
        };
        return;
      }
      if (action.type === "set-movement" && action.jump === true) {
        if (action.forward === true) {
          driver.currentObservation = {
            ...current,
            player: {
              ...current.player,
              air: 300,
              position: { ...current.player.position, y: 30 },
            },
          };
          return;
        }
        ascending = true;
        return;
      }
      if (action.type === "reset-movement") {
        ascending = false;
      }
    };
    driver.observationResolver = () =>
      Effect.sync(() => {
        if (!ascending) {
          return driver.currentObservation;
        }
        const current = driver.currentObservation;
        const y = Math.min(64, current.player.position.y + 1);
        driver.currentObservation = {
          ...current,
          player: {
            ...current.player,
            air: 300,
            position: { ...current.player.position, y },
          },
        };
        if (y >= 64) {
          resolveEscaped();
        }
        return driver.currentObservation;
      });

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (!driver.tasks.some((task) => task.type === "collect-blocks")) {
            yield* Effect.sleep(1);
          }
          driver.currentObservation = observation({
            air: 100,
            position: { x: 0.5, y: 28, z: 0.5 },
          });
          yield* Effect.promise(() => escaped).pipe(Effect.timeout("10 seconds"));
          yield* run.stop;
        }),
      ),
    );

    expect(driver.paths).toHaveLength(1);
    expect(driver.paths[0]?.policy.avoidFluids).toBe(false);
    expect(driver.currentObservation.player.position.y).toBe(64);
  }, 15_000);

  it("keeps recovering after a short water column opens into a deep cave", async () => {
    const driver = new FakeBeatGameDriver();
    driver.surfaceColumns = [
      {
        x: 0,
        z: 0,
        loaded: true,
        surfaceY: 63,
        blockId: "minecraft:grass_block",
        biomeId: "minecraft:plains",
        skyLight: 15,
        blockLight: 0,
      },
    ];
    driver.currentObservation = observation({
      air: 300,
      counts: {
        "minecraft:oak_log": 3,
        "minecraft:stone_pickaxe": 1,
        "minecraft:wooden_sword": 1,
      },
      position: { x: 0.5, y: 28, z: 0.5 },
    });
    let deepSurfaceCollectionCount = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "collect-blocks" && driver.currentObservation.player.position.y < 60) {
          deepSurfaceCollectionCount += 1;
        }
      }).pipe(Effect.andThen(Effect.never));
    driver.blockQueryResolver = (query) => {
      const position = {
        x: Math.floor(query.center.x),
        y: Math.floor(query.center.y),
        z: Math.floor(query.center.z),
        dimension: query.center.dimension,
      };
      const submerged = driver.currentObservation.player.position.y < 29;
      if (query.selector.blockIds?.includes("minecraft:water") === true) {
        return submerged
          ? [
              blockObservation(position, {
                blockId: "minecraft:water",
                diggable: false,
                replaceable: true,
              }),
            ]
          : [];
      }
      if (query.selector.blockIds === undefined) {
        return [
          blockObservation(position, {
            blockId: submerged ? "minecraft:water" : "minecraft:air",
            diggable: false,
            replaceable: true,
          }),
        ];
      }
      return [];
    };
    let resolveEscaped!: () => void;
    const escaped = new Promise<void>((resolve) => {
      resolveEscaped = resolve;
    });
    driver.pathResolver = (position, radius, policy) => {
      driver.paths.push({ position, radius, policy });
      if (driver.paths.length === 1) {
        return Effect.fail(
          new BeatGameDriverError({
            operation: "pathfind",
            code: "unreachable",
            retryable: true,
            message: "The water blocks the first surface route",
          }),
        );
      }
      return Effect.sync(() => {
        driver.currentObservation = {
          ...driver.currentObservation,
          player: {
            ...driver.currentObservation.player,
            position,
          },
        };
        resolveEscaped();
      });
    };
    driver.actionObserver = (action) => {
      if (action.type === "look") {
        driver.currentObservation = {
          ...driver.currentObservation,
          player: {
            ...driver.currentObservation.player,
            rotation: { yaw: action.yaw, pitch: action.pitch },
          },
        };
        return;
      }
      if (action.type === "set-movement" && action.jump === true) {
        driver.currentObservation = {
          ...driver.currentObservation,
          player: {
            ...driver.currentObservation.player,
            air: 300,
            position: {
              ...driver.currentObservation.player.position,
              y: 29,
            },
          },
        };
      }
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          yield* Effect.promise(() => escaped).pipe(Effect.timeout("10 seconds"));
          yield* run.stop;
        }),
      ),
    );

    expect(driver.paths).toHaveLength(2);
    expect(driver.paths[0]?.policy.avoidFluids).toBe(true);
    expect(driver.paths[1]).toEqual(
      expect.objectContaining({
        position: {
          x: 0.5,
          y: 64,
          z: 0.5,
          dimension: "minecraft:overworld",
        },
        policy: expect.objectContaining({ avoidFluids: true }),
      }),
    );
    expect(driver.currentObservation.player.position.y).toBe(64);
    expect(deepSurfaceCollectionCount).toBe(0);
  }, 15_000);

