  it("tries another water source after the server rejects sightline clearing", async () => {
    const driver = new FakeBeatGameDriver();
    const sources = [3, 8].map((x) =>
      blockObservation(
        {
          x,
          y: 64,
          z: 0,
          dimension: "minecraft:overworld",
        },
        {
          blockId: "minecraft:water",
          properties: { level: "0" },
          replaceable: true,
          solid: false,
        },
      ),
    );
    const obstruction = blockObservation(
      {
        x: 1,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      { blockId: "minecraft:stone" },
    );
    driver.currentObservation = observation({
      counts: {
        "minecraft:bucket": 1,
        "minecraft:cobblestone": 20,
        "minecraft:cooked_beef": 8,
        "minecraft:iron_ingot": 7,
        "minecraft:oak_log": 8,
        "minecraft:shield": 1,
        "minecraft:stone_pickaxe": 1,
        "minecraft:stone_sword": 1,
        "minecraft:wooden_sword": 1,
      },
    });
    driver.blockQueryResolver = ({ selector }) =>
      selector.blockIds?.length === 1 &&
      selector.blockIds[0] === "minecraft:water" &&
      selector.properties?.level === "0"
        ? sources
        : [];
    const resolvePath = driver.pathResolver;
    driver.pathResolver = (position, radius, policy) =>
      resolvePath(position, radius, policy).pipe(
        Effect.andThen(position.x === sources[1]?.position.x ? Effect.never : Effect.void),
      );
    driver.raycastResolver = () => ({
      block: obstruction,
      distance: 1.5,
    });
    driver.actionResolver = (action) => {
      if (action.type === "look") {
        driver.currentObservation = observation({
          counts: driver.currentObservation.inventory.counts,
          rotation: { yaw: action.yaw, pitch: action.pitch },
        });
      }
      return action.type === "dig-block"
        ? Effect.fail(
            new BeatGameDriverError({
              operation: "act:dig-block",
              code: "failed_precondition",
              retryable: false,
              message: "The server rejected breaking the target block",
            }),
          )
        : Effect.succeed({});
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (driver.paths.length < 2) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
          yield* run.awaitCompletion.pipe(Effect.result);
        }),
      ),
    );

    expect(driver.paths.slice(0, 2).map(({ position }) => position)).toEqual(
      sources.map(({ position }) => position),
    );
    expect(driver.actions).toContainEqual({
      type: "dig-block",
      position: obstruction.position,
    });
  });

  it("replaces a pickaxe broken on approach before exposing a fluid source", async () => {
    const driver = new FakeBeatGameDriver();
    const source = {
      x: 18,
      y: 66,
      z: 156,
      dimension: "minecraft:overworld",
    } as const;
    const playerPosition = {
      x: 19.5,
      y: 64,
      z: 158.5,
      dimension: "minecraft:overworld",
    } as const;
    const obstruction = {
      x: 18,
      y: 66,
      z: 157,
      dimension: "minecraft:overworld",
    } as const;
    const craftingTable = {
      x: 20,
      y: 64,
      z: 158,
      dimension: "minecraft:overworld",
    } as const;
    let sourceExposed = false;
    let approachBrokePickaxe = false;
    driver.currentObservation = observation({
      position: playerPosition,
      counts: {
        "minecraft:cooked_beef": 8,
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
        "minecraft:iron_ingot": 7,
        "minecraft:stone_pickaxe": 1,
        "minecraft:bucket": 1,
        "minecraft:shield": 1,
      },
    });
    driver.blockQueryResolver = ({ radius, selector }) => {
      if (radius === 0.25 && Object.keys(selector).length === 0) {
        return [
          blockObservation(source, {
            blockId: "minecraft:water",
            properties: { level: "0" },
            replaceable: true,
          }),
        ];
      }
      if (
        selector.blockIds?.includes("minecraft:water") === true &&
        selector.properties?.level === "0"
      ) {
        return [
          blockObservation(source, {
            blockId: "minecraft:water",
            properties: { level: "0" },
            replaceable: true,
          }),
        ];
      }
      if (selector.blockIds?.includes("minecraft:crafting_table") === true) {
        return [
          blockObservation(craftingTable, {
            blockId: "minecraft:crafting_table",
          }),
        ];
      }
      return [];
    };
    driver.recipeResolver = (resultItemId) => [
      {
        recipeId: resultItemId,
        recipeType: "minecraft:crafting",
        resultItemId,
        resultCount: 1,
        ingredients: [],
      },
    ];
    driver.craftabilityResolver = () => ({
      canCraft: true,
      maximumCraftCount: 1,
      requiredStation: "minecraft:crafting_table",
      missing: [],
    });
    const resolvePath = driver.pathResolver;
    driver.pathResolver = (position, radius, policy) =>
      resolvePath(position, radius, policy).pipe(
        Effect.tap(() =>
          Effect.sync(() => {
            if (
              !approachBrokePickaxe &&
              position.x === source.x &&
              position.y === source.y &&
              position.z === source.z
            ) {
              approachBrokePickaxe = true;
              const counts = {
                ...driver.currentObservation.inventory.counts,
              };
              delete counts["minecraft:stone_pickaxe"];
              driver.currentObservation = observation({
                position: playerPosition,
                counts,
              });
            }
          }),
        ),
      );
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "craft" && task.recipeId === "minecraft:stone_pickaxe") {
          driver.currentObservation = observation({
            position: playerPosition,
            counts: {
              ...driver.currentObservation.inventory.counts,
              "minecraft:stone_pickaxe": 1,
            },
          });
        }
      });
    driver.raycastResolver = ({ includeFluids }) => {
      if (sourceExposed) {
        return includeFluids === true
          ? {
              block: blockObservation(source, {
                blockId: "minecraft:water",
                properties: { level: "0" },
                replaceable: true,
              }),
              distance: 2.4,
            }
          : { distance: 2.4 };
      }
      return {
        block: blockObservation(obstruction),
        distance: 1.4,
      };
    };
    driver.actionResolver = (action) => {
      if (action.type === "look") {
        driver.currentObservation = observation({
          position: playerPosition,
          counts: driver.currentObservation.inventory.counts,
          rotation: { yaw: action.yaw, pitch: action.pitch },
        });
      }
      if (
        action.type === "dig-block" &&
        action.position.x === obstruction.x &&
        action.position.y === obstruction.y &&
        action.position.z === obstruction.z
      ) {
        sourceExposed = true;
      }
      return action.type === "use-item" ? Effect.never : Effect.succeed({});
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (!driver.actions.some((action) => action.type === "use-item")) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.paths).toContainEqual(
      expect.objectContaining({
        position: source,
        radius: 3,
      }),
    );
    expect(driver.tasks).toContainEqual(
      expect.objectContaining({
        type: "craft",
        recipeId: "minecraft:stone_pickaxe",
      }),
    );
    expect(driver.raycasts).toHaveLength(2);
    expect(driver.actions).toContainEqual({
      type: "dig-block",
      position: obstruction,
    });
    expect(driver.actions.slice(-2)).toEqual([
      {
        type: "select-item",
        selector: { itemIds: ["minecraft:bucket"] },
      },
      { type: "use-item", hand: "main" },
    ]);
    expect(driver.actions).not.toContainEqual(
      expect.objectContaining({
        type: "interact-block",
      }),
    );
  });

  it("approaches lava from a dry ledge while standing in shallow water", async () => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const source = {
      x: 0,
      y: -52,
      z: 0,
      dimension: "minecraft:overworld",
    } as const;
    const safeStand = {
      x: 2,
      y: -50,
      z: 0,
      dimension: "minecraft:overworld",
    } as const;
    const borderlineStand = {
      x: 3,
      y: -50,
      z: 0,
      dimension: "minecraft:overworld",
    } as const;
    const start = {
      x: 4.5,
      y: -51,
      z: 0.5,
      dimension: "minecraft:overworld",
    } as const;
    driver.currentObservation = observation({
      position: start,
      counts: {
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
        "minecraft:cooked_beef": 8,
        "minecraft:iron_ingot": 7,
        "minecraft:bucket": 1,
        "minecraft:flint_and_steel": 1,
        "minecraft:iron_pickaxe": 1,
        "minecraft:shield": 1,
        "minecraft:water_bucket": 1,
      },
    });
    driver.blockQueryResolver = ({ center, radius, selector }) => {
      if (
        selector.blockIds?.includes("minecraft:water") === true &&
        selector.blockIds.length > 1 &&
        Math.floor(center.x) === Math.floor(start.x) &&
        Math.floor(center.y) === Math.floor(start.y) &&
        Math.floor(center.z) === Math.floor(start.z)
      ) {
        return [
          blockObservation(
            {
              x: Math.floor(start.x),
              y: Math.floor(start.y),
              z: Math.floor(start.z),
              dimension: start.dimension,
            },
            {
              blockId: "minecraft:water",
              properties: { level: "0" },
              replaceable: true,
            },
          ),
        ];
      }
      if (
        selector.blockIds?.includes("minecraft:lava") === true &&
        selector.properties?.level === "0"
      ) {
        return [
          blockObservation(source, {
            blockId: "minecraft:lava",
            properties: { level: "0" },
            replaceable: true,
          }),
        ];
      }
      if (
        selector.blockIds?.includes("minecraft:lava") === true &&
        selector.properties?.level === undefined
      ) {
        return [];
      }
      if (radius === 4.9 && Object.keys(selector).length === 0) {
        return [
          blockObservation(safeStand, {
            blockId: "minecraft:air",
            replaceable: true,
          }),
          blockObservation(
            { ...safeStand, y: safeStand.y + 1 },
            {
              blockId: "minecraft:air",
              replaceable: true,
            },
          ),
          blockObservation({ ...safeStand, y: safeStand.y - 1 }),
          blockObservation(borderlineStand, {
            blockId: "minecraft:air",
            replaceable: true,
          }),
          blockObservation(
            { ...borderlineStand, y: borderlineStand.y + 1 },
            {
              blockId: "minecraft:air",
              replaceable: true,
            },
          ),
          blockObservation({ ...borderlineStand, y: borderlineStand.y - 1 }),
        ];
      }
      const position = {
        x: Math.floor(center.x),
        y: Math.floor(center.y),
        z: Math.floor(center.z),
        dimension: center.dimension,
      };
      if (
        position.x === safeStand.x &&
        position.z === safeStand.z &&
        (position.y === safeStand.y || position.y === safeStand.y + 1)
      ) {
        return [
          blockObservation(position, {
            blockId: "minecraft:air",
            replaceable: true,
          }),
        ];
      }
      if (
        position.x === safeStand.x &&
        position.y === safeStand.y - 1 &&
        position.z === safeStand.z
      ) {
        return [blockObservation(position)];
      }
      return [
        blockObservation(position, {
          blockId: "minecraft:lava",
          replaceable: true,
        }),
      ];
    };
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
        if (radius === 0.75 || radius === 2) {
          driver.currentObservation = observation({
            position,
            counts: driver.currentObservation.inventory.counts,
          });
        }
      });
    driver.raycastResolver = ({ includeFluids }) =>
      includeFluids === true
        ? {
            block: blockObservation(source, {
              blockId: "minecraft:lava",
              properties: { level: "0" },
              replaceable: true,
            }),
            distance: 3,
          }
        : { distance: 3 };
    let resolveUseItemStarted!: () => void;
    const useItemStarted = new Promise<void>((resolve) => {
      resolveUseItemStarted = resolve;
    });
    let resolveUseItemInterrupted!: () => void;
    const useItemInterrupted = new Promise<void>((resolve) => {
      resolveUseItemInterrupted = resolve;
    });
    driver.actionResolver = (action) => {
      if (action.type === "look") {
        driver.currentObservation = observation({
          position: driver.currentObservation.player.position,
          counts: driver.currentObservation.inventory.counts,
          rotation: { yaw: action.yaw, pitch: action.pitch },
        });
      }
      return action.type === "use-item"
        ? Effect.sync(resolveUseItemStarted).pipe(
            Effect.andThen(Effect.never),
            Effect.onInterrupt(() => Effect.sync(resolveUseItemInterrupted)),
          )
        : Effect.succeed({});
    };
    await Effect.runPromise(
      store.save(
        checkpoint(BeatGamePhase.ENTER_NETHER, {
          runId: "safe-lava-approach-run",
          teamId: "safe-lava-approach-team",
        }),
        undefined,
      ),
    );

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          runId: "safe-lava-approach-run",
          team: { teamId: "safe-lava-approach-team" },
          checkpointStore: store,
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              yield* Effect.promise(() => useItemStarted).pipe(Effect.timeout("5 seconds"));
              driver.currentObservation = observation({
                position: driver.currentObservation.player.position,
                counts: {
                  ...driver.currentObservation.inventory.counts,
                  "minecraft:bucket": 0,
                  "minecraft:lava_bucket": 1,
                },
                rotation: driver.currentObservation.player.rotation,
              });
              yield* Effect.promise(() => useItemInterrupted).pipe(Effect.timeout("5 seconds"));
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.paths).toContainEqual({
      position: {
        x: 2.5,
        y: -50,
        z: 0.5,
        dimension: "minecraft:overworld",
      },
      radius: 0.75,
      policy: expect.objectContaining({
        avoidFluids: true,
        maxFallDistance: 1,
      }),
    });
    expect(driver.paths).not.toContainEqual(
      expect.objectContaining({
        position: source,
        radius: 3,
      }),
    );
    expect(driver.paths).not.toContainEqual(
      expect.objectContaining({
        position: {
          x: 3.5,
          y: -50,
          z: 0.5,
          dimension: "minecraft:overworld",
        },
      }),
    );
    expect(driver.actions.some((action) => action.type === "dig-block")).toBe(false);
    expect(driver.blockQueries).toContainEqual(
      expect.objectContaining({
        center: {
          x: 0.5,
          y: -51.5,
          z: 0.5,
          dimension: "minecraft:overworld",
        },
        radius: 4.9,
        maximumResults: 500,
      }),
    );
    expect(driver.blockQueries).toContainEqual({
      center: {
        x: 0.5,
        y: -51.5,
        z: 0.5,
        dimension: "minecraft:overworld",
      },
      radius: 0.25,
      selector: {
        blockIds: ["minecraft:lava"],
        properties: { level: "0" },
      },
      maximumResults: 1,
    });
    expect(driver.actions).toContainEqual({
      type: "use-item",
      hand: "main",
    });
  });

  it("prefers a source-rich lava pool over a nearer lone source", async () => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const start = {
      x: 0.5,
      y: -50,
      z: 0.5,
      dimension: "minecraft:overworld",
    } as const;
    const loneSource = blockObservation(
      {
        x: 4,
        y: -52,
        z: 0,
        dimension: start.dimension,
      },
      {
        blockId: "minecraft:lava",
        properties: { level: "0" },
        replaceable: true,
      },
    );
    const poolSources = [
      { x: 20, z: 0 },
      { x: 20, z: 1 },
      { x: 21, z: 0 },
      { x: 21, z: 1 },
    ].map(({ x, z }) =>
      blockObservation(
        {
          x,
          y: -52,
          z,
          dimension: start.dimension,
        },
        {
          blockId: "minecraft:lava",
          properties: { level: "0" },
          replaceable: true,
        },
      ),
    );
    const loneStand = {
      x: 2,
      y: -50,
      z: 0,
      dimension: start.dimension,
    } as const;
    const poolStand = {
      x: 18,
      y: -50,
      z: 0,
      dimension: start.dimension,
    } as const;
    const standVolume = (stand: BeatGameBlockPosition) => [
      blockObservation(stand, {
        blockId: "minecraft:air",
        replaceable: true,
      }),
      blockObservation(
        { ...stand, y: stand.y + 1 },
        {
          blockId: "minecraft:air",
          replaceable: true,
        },
      ),
      blockObservation({ ...stand, y: stand.y - 1 }),
    ];
    const sources = [loneSource, ...poolSources];
    driver.currentObservation = observation({
      position: start,
      counts: {
        "minecraft:bucket": 1,
        "minecraft:cobblestone": 20,
        "minecraft:cooked_beef": 8,
        "minecraft:flint_and_steel": 1,
        "minecraft:iron_ingot": 7,
        "minecraft:iron_pickaxe": 1,
        "minecraft:oak_log": 8,
        "minecraft:shield": 1,
        "minecraft:stone_sword": 1,
        "minecraft:water_bucket": 1,
      },
    });
    driver.blockQueryResolver = ({ center, radius, selector }) => {
      if (
        selector.blockIds?.includes("minecraft:lava") === true &&
        selector.properties?.level === "0"
      ) {
        if (radius > 0.25) {
          return sources;
        }
        return sources.filter(
          ({ position }) =>
            position.x === Math.floor(center.x) &&
            position.y === Math.floor(center.y) &&
            position.z === Math.floor(center.z),
        );
      }
      if (radius === 4.9 && Object.keys(selector).length === 0) {
        return standVolume(center.x < 10 ? loneStand : poolStand);
      }
      return [];
    };
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
        if (radius === 0.75 || radius === 2) {
          driver.currentObservation = observation({
            position,
            counts: driver.currentObservation.inventory.counts,
          });
        }
      });
    driver.raycastResolver = ({ includeFluids }) => {
      if (includeFluids !== true) {
        return { distance: 2 };
      }
      const source =
        driver.currentObservation.player.position.x >= 10 ? poolSources[0]! : loneSource;
      return { block: source, distance: 2 };
    };
    driver.actionResolver = (action) => {
      if (action.type === "look") {
        driver.currentObservation = observation({
          position: driver.currentObservation.player.position,
          counts: driver.currentObservation.inventory.counts,
          rotation: { yaw: action.yaw, pitch: action.pitch },
        });
      }
      return action.type === "use-item" ? Effect.never : Effect.succeed({});
    };
    await Effect.runPromise(
      store.save(
        checkpoint(BeatGamePhase.ENTER_NETHER, {
          runId: "clustered-lava-source-run",
          teamId: "clustered-lava-source-team",
        }),
        undefined,
      ),
    );

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            runId: "clustered-lava-source-run",
            team: { teamId: "clustered-lava-source-team" },
            checkpointStore: store,
            strategy: { observationPollMs: 1 },
          });
          while (!driver.actions.some((action) => action.type === "use-item")) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
          yield* run.awaitCompletion.pipe(Effect.result);
        }).pipe(Effect.timeout("5 seconds")),
      ),
    );

    expect(driver.paths.find(({ radius }) => radius === 0.75)).toEqual(
      expect.objectContaining({
        position: {
          x: poolStand.x + 0.5,
          y: poolStand.y,
          z: poolStand.z + 0.5,
          dimension: poolStand.dimension,
        },
      }),
    );
    expect(driver.paths).not.toContainEqual(
      expect.objectContaining({
        position: {
          x: loneStand.x + 0.5,
          y: loneStand.y,
          z: loneStand.z + 0.5,
          dimension: loneStand.dimension,
        },
      }),
    );
  });

