  it("recycles placed gravel until it produces flint", async () => {
    const driver = new FakeBeatGameDriver();
    const wetSupport = {
      x: 1,
      y: 63,
      z: 0,
      dimension: "minecraft:overworld",
    } as const;
    const firstSupport = {
      x: 2,
      y: 63,
      z: 0,
      dimension: "minecraft:overworld",
    } as const;
    const secondSupport = { ...firstSupport, x: 3 };
    const supports = [wetSupport, firstSupport, secondSupport] as const;
    let gravelPlaced = false;
    let rejectedPlacement = false;
    let placedTarget: BeatGameBlockPosition = {
      ...firstSupport,
      y: firstSupport.y + 1,
    };
    let digs = 0;
    driver.currentObservation = observation({
      counts: {
        "minecraft:cooked_beef": 8,
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
        "minecraft:iron_ingot": 7,
        "minecraft:stone_pickaxe": 1,
        "minecraft:water_bucket": 1,
        "minecraft:shield": 1,
        "minecraft:gravel": 1,
      },
    });
    driver.blockQueryResolver = (query) => {
      if (query.selector.blockIds?.includes("minecraft:gravel") && gravelPlaced) {
        return [
          blockObservation(placedTarget, {
            blockId: "minecraft:gravel",
          }),
        ];
      }
      if (
        query.selector.blockIds?.includes("minecraft:water") &&
        Math.floor(query.center.x) === wetSupport.x &&
        Math.floor(query.center.y) === wetSupport.y + 1 &&
        Math.floor(query.center.z) === wetSupport.z
      ) {
        return [
          blockObservation(
            {
              ...wetSupport,
              y: wetSupport.y + 1,
            },
            {
              blockId: "minecraft:water",
              replaceable: true,
            },
          ),
        ];
      }
      if (query.selector.replaceable === false) {
        return supports.map((support) => blockObservation(support));
      }
      if (query.selector.replaceable === true) {
        const candidate = {
          x: Math.floor(query.center.x),
          y: Math.floor(query.center.y),
          z: Math.floor(query.center.z),
          dimension: query.center.dimension,
        };
        return [
          blockObservation(candidate, {
            blockId: "minecraft:air",
            diggable: false,
            replaceable: true,
          }),
        ];
      }
      return [];
    };
    driver.actionResolver = (action) => {
      if (action.type === "place-block" && !rejectedPlacement) {
        rejectedPlacement = true;
        return Effect.fail(
          new BeatGameDriverError({
            operation: "placeBlock",
            retryable: true,
            message: "The held item could not be used on the target block",
          }),
        );
      }
      return Effect.sync(() => {
        if (action.type === "place-block") {
          gravelPlaced = true;
          placedTarget = {
            ...action.against,
            y: action.against.y + 1,
          };
        }
        if (action.type === "dig-block") {
          digs += 1;
          gravelPlaced = false;
          driver.currentObservation = observation({
            position: {
              x: placedTarget.x + 0.5,
              y: placedTarget.y,
              z: placedTarget.z + 0.5,
            },
            counts: {
              ...driver.currentObservation.inventory.counts,
              "minecraft:gravel": digs === 1 ? 1 : 0,
              ...(digs === 1 ? {} : { "minecraft:flint": 1 }),
            },
          });
        }
        return {};
      });
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (driver.actions.filter((action) => action.type === "dig-block").length < 2) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.actions).toContainEqual({
      type: "select-item",
      selector: { itemIds: ["minecraft:gravel"] },
    });
    expect(driver.actions).toContainEqual({
      type: "place-block",
      against: firstSupport,
      face: "up",
      hand: "main",
    });
    expect(driver.actions).toContainEqual({
      type: "dig-block",
      position: { ...firstSupport, y: firstSupport.y + 1 },
    });
    expect(driver.actions).toContainEqual({
      type: "place-block",
      against: secondSupport,
      face: "up",
      hand: "main",
    });
    expect(driver.actions).toContainEqual({
      type: "dig-block",
      position: { ...secondSupport, y: secondSupport.y + 1 },
    });
    expect(driver.actions).not.toContainEqual({
      type: "place-block",
      against: wetSupport,
      face: "up",
      hand: "main",
    });
    expect(rejectedPlacement).toBe(true);
    expect(driver.actions.filter(({ type }) => type === "place-block")).toHaveLength(3);
    expect(
      driver.paths
        .filter(({ radius }) => radius === 3)
        .every(({ policy }) => policy.avoidFluids === true),
    ).toBe(true);
  });

  it("collects replacement gravel without entering fluid", async () => {
    const driver = new FakeBeatGameDriver();
    driver.currentObservation = observation({
      counts: {
        "minecraft:cooked_beef": 8,
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
        "minecraft:iron_ingot": 7,
        "minecraft:stone_pickaxe": 1,
        "minecraft:water_bucket": 1,
        "minecraft:shield": 1,
      },
    });
    let resolveGravelCollection!: () => void;
    const gravelCollectionStarted = new Promise<void>((resolve) => {
      resolveGravelCollection = resolve;
    });
    driver.taskResolver = (task) => {
      driver.tasks.push(task);
      if (task.type === "collect-blocks" && task.blockIds.includes("minecraft:gravel")) {
        resolveGravelCollection();
        return Effect.never;
      }
      return Effect.void;
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          yield* Effect.promise(() => gravelCollectionStarted).pipe(Effect.timeout("5 seconds"));
          yield* run.stop;
        }),
      ),
    );

    expect(driver.tasks.at(-1)).toMatchObject({
      type: "collect-blocks",
      blockIds: ["minecraft:gravel"],
      count: 8,
      avoidSubmergedTargets: true,
    });
    expect(driver.taskPolicies.at(-1)?.avoidFluids).toBe(true);
  });

