  it("uses a distinct idempotency key for repeated task invocations", async () => {
    const driver = new FakeBeatGameDriver();
    const task = {
      type: "collect-blocks" as const,
      blockIds: ["minecraft:oak_log"],
      count: 1,
      searchRadius: 32,
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          runId: "task-invocation-run",
          team: { teamId: "task-invocation-team" },
          strategy: { observationPollMs: 1 },
          hooks: {
            satisfyRequirement: ({ driver: actionDriver, strategy }) =>
              Effect.gen(function* () {
                yield* actionDriver.runTask(task, strategy.path);
                yield* actionDriver.runTask(task, strategy.path);
                return yield* Effect.never;
              }),
          },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (driver.taskExecutions.length < 2) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    const keys = driver.taskExecutions.map(({ idempotencyKey }) => idempotencyKey);
    expect(keys).toHaveLength(2);
    expect(keys[0]).toMatch(/^beat-game:[0-9a-f-]{36}:[0-9a-f]{16}:1:[0-9a-f]{16}$/u);
    expect(keys[1]).toMatch(/^beat-game:[0-9a-f-]{36}:[0-9a-f]{16}:2:[0-9a-f]{16}$/u);
    expect(keys[0]).not.toBe(keys[1]);
  });

