  it("enters water to pursue nearby food when hunger is critical", async () => {
    const driver = new FakeBeatGameDriver();
    const salmon = {
      connectionEpoch: "epoch-1",
      networkId: 46,
      entityType: "minecraft:salmon",
      position: {
        x: 28,
        y: 61,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 3,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    driver.currentObservation = observation({
      food: 6,
      health: 8,
      counts: {
        "minecraft:iron_ingot": 7,
        "minecraft:oak_log": 8,
        "minecraft:shield": 1,
        "minecraft:stone_pickaxe": 1,
        "minecraft:stone_sword": 1,
      },
    });
    driver.entityResults = [salmon];
    driver.blockQueryResolver = (query) => {
      if (query.selector.blockIds?.includes("minecraft:water") !== true) {
        return [];
      }
      const water = blockObservation(
        {
          x: 1,
          y: 64,
          z: 0,
          dimension: "minecraft:overworld",
        },
        {
          blockId: "minecraft:water",
          diggable: false,
          replaceable: true,
        },
      );
      return query.radius > 1 || Math.floor(query.center.x) === 1 ? [water] : [];
    };
    driver.xzPathResolver = (x, z, dimension, radius, policy) =>
      Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
      }).pipe(
        Effect.andThen(
          Effect.fail(
            new BeatGameDriverError({
              operation: "pathfindXZ",
              code: "unreachable",
              retryable: true,
              message: "No dry route leaves the island",
            }),
          ),
        ),
      );
    let directPathAttempts = 0;
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
        directPathAttempts += 1;
      }).pipe(
        Effect.flatMap(() =>
          directPathAttempts === 1
            ? Effect.fail(
                new BeatGameDriverError({
                  operation: "pathfind",
                  code: "unreachable",
                  retryable: true,
                  message: "The pathfinder cannot step from the bridge into water",
                }),
              )
            : Effect.sync(() => {
                driver.currentObservation = observation({
                  position,
                  food: 6,
                  health: 8,
                  counts: {
                    "minecraft:iron_ingot": 7,
                    "minecraft:oak_log": 8,
                    "minecraft:shield": 1,
                    "minecraft:stone_pickaxe": 1,
                    "minecraft:stone_sword": 1,
                  },
                });
              }),
        ),
      );
    driver.actionObserver = (action) => {
      if (action.type !== "set-movement" || action.forward !== true || action.jump !== true) {
        return;
      }
      driver.currentObservation = observation({
        position: {
          x: 1.5,
          y: 64,
          z: 0.5,
          dimension: "minecraft:overworld",
        },
        food: 6,
        health: 8,
        counts: driver.currentObservation.inventory.counts,
      });
    };
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "attack-entity") {
          driver.entityResults = [];
        }
      });

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (!driver.tasks.some((task) => task.type === "attack-entity")) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
        }),
      ),
    );

    expect(driver.xzPaths).toHaveLength(0);
    expect(driver.paths).toHaveLength(0);
    const attackIndex = driver.tasks.findIndex((task) => task.type === "attack-entity");
    expect(driver.tasks[attackIndex]).toEqual(
      expect.objectContaining({
        target: expect.objectContaining({
          connectionEpoch: salmon.connectionEpoch,
          networkId: salmon.networkId,
        }),
      }),
    );
    expect(driver.taskPolicies[attackIndex]).toMatchObject({
      allowMining: false,
      allowPlacing: false,
      avoidFluids: false,
      sprint: true,
    });
  });

