  it("moves on after an animal remains unreachable", async () => {
    const driver = new FakeBeatGameDriver();
    driver.currentObservation = observation({
      counts: {
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
      },
    });
    const cow = {
      connectionEpoch: "epoch-1",
      networkId: 42,
      entityType: "minecraft:cow",
      position: {
        x: 8,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    driver.entityResults = [cow];
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
      }).pipe(
        Effect.andThen(
          task.type === "attack-entity"
            ? Effect.fail(
                new BeatGameDriverError({
                  operation: "task.attack-entity",
                  code: "unreachable",
                  retryable: true,
                  message: "Unable to reach the target entity",
                }),
              )
            : Effect.void,
        ),
      );
    driver.xzPathResolver = (x, z, dimension, radius, policy) =>
      Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
      }).pipe(Effect.andThen(Effect.never));
    let rememberedTargets: readonly string[] = [];

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: {
            observationPollMs: 1,
            entitySearchRadius: 320,
          },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (driver.xzPaths.length === 0) {
                yield* Effect.sleep(1);
              }
              rememberedTargets = (yield* run.snapshot).checkpoint.memory.unreachable.map(
                ({ key }) => key,
              );
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    const attackIndex = driver.tasks.findIndex((task) => task.type === "attack-entity");
    expect(driver.taskPolicies[attackIndex]).toMatchObject({
      allowPlacing: true,
    });
    expect(driver.xzPaths[0]?.policy).toMatchObject({
      allowMining: false,
      allowPlacing: false,
    });
    expect(driver.xzPaths[0]).toMatchObject({
      x: 32,
      z: 0,
    });
    expect(rememberedTargets).toContain("target:epoch-1:42");
  });

  it("retries an unreachable animal after it moves", async () => {
    const driver = new FakeBeatGameDriver();
    const preparedItems = {
      "minecraft:oak_log": 8,
      "minecraft:cobblestone": 20,
      "minecraft:stone_sword": 1,
    };
    const cow = {
      connectionEpoch: "epoch-1",
      networkId: 43,
      entityType: "minecraft:cow",
      position: {
        x: 8,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    const movedCow = {
      ...cow,
      position: { ...cow.position, x: 2 },
      observedAt: "2026-01-01T00:00:01.000Z",
    } as const;
    driver.currentObservation = observation({ counts: preparedItems });
    driver.entityResults = [cow];
    let attackAttempts = 0;
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "attack-entity") {
          attackAttempts += 1;
          driver.entityResults = [movedCow];
        }
        return attackAttempts;
      }).pipe(
        Effect.flatMap((attempt) =>
          task.type !== "attack-entity"
            ? Effect.void
            : attempt === 1
              ? Effect.fail(
                  new BeatGameDriverError({
                    operation: "task.attack-entity",
                    code: "unreachable",
                    retryable: true,
                    message: "The animal moved away from its original route",
                  }),
                )
              : Effect.never,
        ),
      );

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: {
            observationPollMs: 1,
            entitySearchRadius: 320,
          },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (driver.tasks.filter((task) => task.type === "attack-entity").length < 2) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.tasks.filter((task) => task.type === "attack-entity")).toEqual([
      expect.objectContaining({
        target: expect.objectContaining({ position: cow.position }),
      }),
      expect.objectContaining({
        target: expect.objectContaining({ position: movedCow.position }),
      }),
    ]);
  });

  it("picks up a nearby required resource before gathering more", async () => {
    const driver = new FakeBeatGameDriver();
    const preparedCounts = {
      "minecraft:oak_log": 8,
      "minecraft:cobblestone": 20,
      "minecraft:cooked_beef": 8,
      "minecraft:stone_sword": 1,
    };
    const droppedIron = {
      connectionEpoch: "epoch-1",
      networkId: 45,
      entityType: "minecraft:item",
      itemId: "minecraft:iron_ingot",
      position: {
        x: 2,
        y: 64,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 5,
      observedAt: "2026-01-01T00:00:00.000Z",
    } as const;
    driver.currentObservation = observation({ counts: preparedCounts });
    driver.entityQueryResolver = (query) =>
      query.selector.entityTypes?.includes("minecraft:item") === true &&
      (driver.currentObservation.inventory.counts["minecraft:iron_ingot"] ?? 0) === 0
        ? [droppedIron]
        : [];
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
        if (position.x === droppedIron.position.x && position.z === droppedIron.position.z) {
          driver.currentObservation = observation({
            position: droppedIron.position,
            counts: {
              ...preparedCounts,
              "minecraft:iron_ingot": 1,
            },
          });
        }
      });

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              let attempts = 1_000;
              while (
                (driver.currentObservation.inventory.counts["minecraft:iron_ingot"] ?? 0) === 0 &&
                attempts > 0
              ) {
                attempts -= 1;
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(driver.paths).toContainEqual(
      expect.objectContaining({
        position: droppedIron.position,
        policy: expect.objectContaining({
          allowPlacing: false,
          avoidFluids: true,
        }),
      }),
    );
    expect(driver.tasks).not.toContainEqual(
      expect.objectContaining({
        type: "collect-blocks",
      }),
    );
  });

