  it("clears jump headroom while climbing a sealed pocket", async () => {
    const driver = new FakeBeatGameDriver();
    driver.currentObservation = observation({
      position: {
        x: 0.5,
        y: 60,
        z: 0.5,
        dimension: "minecraft:overworld",
      },
      counts: {
        "minecraft:oak_log": 3,
        "minecraft:stone_pickaxe": 1,
        "minecraft:wooden_sword": 1,
      },
    });
    driver.surfaceColumns = [
      {
        x: 3,
        z: 0,
        loaded: true,
        surfaceY: 62,
        blockId: "minecraft:grass_block",
        biomeId: "minecraft:plains",
        skyLight: 15,
        blockLight: 0,
      },
    ];
    const blocks = new Map<string, ReturnType<typeof blockObservation>>();
    const setBlock = (
      position: BeatGameBlockPosition,
      overrides: Parameters<typeof blockObservation>[1] = {},
    ) => {
      blocks.set(
        `${position.x}:${position.y}:${position.z}`,
        blockObservation(position, overrides),
      );
    };
    setBlock({
      x: 0,
      y: 59,
      z: 0,
      dimension: "minecraft:overworld",
    });
    for (let rise = 1; rise <= 3; rise += 1) {
      setBlock({
        x: rise,
        y: 60 + rise - 1,
        z: 0,
        dimension: "minecraft:overworld",
      });
      for (const y of [60 + rise, 61 + rise]) {
        setBlock({
          x: rise,
          y,
          z: 0,
          dimension: "minecraft:overworld",
        });
      }
    }
    for (let rise = 1; rise <= 3; rise += 1) {
      setBlock({
        x: rise - 1,
        y: 61 + rise,
        z: 0,
        dimension: "minecraft:overworld",
      });
    }
    driver.blockQueryResolver = ({ center, radius, selector }) => {
      if (selector.blockIds?.includes("minecraft:water") === true) {
        return [];
      }
      if (radius > 0.25 || Object.keys(selector).length > 0) {
        return [];
      }
      const block = blocks.get(
        `${Math.floor(center.x)}:${Math.floor(center.y)}:${Math.floor(center.z)}`,
      );
      return block === undefined ? [] : [block];
    };
    driver.actionObserver = (action) => {
      if (action.type !== "dig-block") {
        return;
      }
      setBlock(action.position, {
        blockId: "minecraft:air",
        diggable: false,
        replaceable: true,
        solid: false,
      });
    };
    driver.pathResolver = (position, radius, policy) => {
      const record = Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
      });
      if (radius !== 0.35) {
        return record.pipe(
          Effect.andThen(
            Effect.fail(
              new BeatGameDriverError({
                operation: "pathfind",
                code: "unreachable",
                retryable: true,
                message: "No complete path leaves the sealed pocket",
              }),
            ),
          ),
        );
      }
      return record.pipe(
        Effect.flatMap(() => {
          const current = driver.currentObservation.player.position;
          const jumpClearance = blocks.get(
            [Math.floor(current.x), Math.floor(current.y) + 2, Math.floor(current.z)].join(":"),
          );
          return jumpClearance !== undefined && !jumpClearance.replaceable
            ? Effect.fail(
                new BeatGameDriverError({
                  operation: "pathfind",
                  code: "unreachable",
                  retryable: true,
                  message: "The jump headroom is obstructed",
                }),
              )
            : Effect.sync(() => {
                driver.currentObservation = {
                  ...driver.currentObservation,
                  player: {
                    ...driver.currentObservation.player,
                    position,
                  },
                };
              });
        }),
      );
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          yield* Effect.gen(function* () {
            while (driver.currentObservation.player.position.y < 63) {
              yield* Effect.sleep(1);
            }
          }).pipe(Effect.timeout("5 seconds"));
          yield* run.stop;
        }),
      ),
    );

    expect(
      driver.paths.map(({ position, radius, policy }) => ({
        position,
        radius,
        policy,
      })),
    ).toEqual([
      expect.objectContaining({
        position: expect.objectContaining({ x: 3.5, y: 63, z: 0.5 }),
        radius: 1.5,
        policy: expect.objectContaining({
          allowMining: true,
          allowPlacing: true,
          avoidFluids: true,
          maxSearchTimeMs: 2_000,
        }),
      }),
      expect.objectContaining({
        position: expect.objectContaining({ x: 1.5, y: 61, z: 0.5 }),
        radius: 0.35,
        policy: expect.objectContaining({
          allowMining: false,
          allowPlacing: false,
        }),
      }),
      expect.objectContaining({
        position: expect.objectContaining({ x: 2.5, y: 62, z: 0.5 }),
        radius: 0.35,
      }),
      expect.objectContaining({
        position: expect.objectContaining({ x: 3.5, y: 63, z: 0.5 }),
        radius: 0.35,
      }),
    ]);
    expect(driver.actions).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          type: "dig-block",
          position: {
            x: 0,
            y: 62,
            z: 0,
            dimension: "minecraft:overworld",
          },
        }),
        expect.objectContaining({
          type: "dig-block",
          position: {
            x: 1,
            y: 63,
            z: 0,
            dimension: "minecraft:overworld",
          },
        }),
      ]),
    );
    expect(
      driver.tasks.some(
        (task) => task.type === "collect-blocks" && task.blockIds.includes("minecraft:oak_log"),
      ),
    ).toBe(false);
  });

